## Server-Sent Events (SSE)

### Basic SSE

```tsx
// app/api/sse/route.ts
export async function GET() {
  const encoder = new TextEncoder()

  const stream = new ReadableStream({
    async start(controller) {
      let count = 0

      const interval = setInterval(() => {
        const data = `data: ${JSON.stringify({ count: count++, time: new Date().toISOString() })}\n\n`
        controller.enqueue(encoder.encode(data))

        if (count >= 10) {
          clearInterval(interval)
          controller.close()
        }
      }, 1000)
    },
  })

  return new Response(stream, {
    headers: {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache',
      'Connection': 'keep-alive',
    },
  })
}
```

### SSE with Event Types

```tsx
// app/api/events/route.ts
export async function GET() {
  const encoder = new TextEncoder()

  const stream = new ReadableStream({
    async start(controller) {
      // Send a named event
      const sendEvent = (eventType: string, data: unknown) => {
        const message = `event: ${eventType}\ndata: ${JSON.stringify(data)}\n\n`
        controller.enqueue(encoder.encode(message))
      }

      // Initial connection event
      sendEvent('connected', { status: 'ok' })

      // Simulate notifications
      const notifications = await getNotifications()
      for (const notification of notifications) {
        sendEvent('notification', notification)
        await delay(500)
      }

      // Final event
      sendEvent('complete', { total: notifications.length })
      controller.close()
    },
  })

  return new Response(stream, {
    headers: {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache',
      'Connection': 'keep-alive',
    },
  })
}
```

### Client-Side SSE Consumer

```tsx
// components/sse-consumer.tsx
'use client'

import { useEffect, useState } from 'react'

interface Event {
  type: string
  data: unknown
}

export function SSEConsumer() {
  const [events, setEvents] = useState<Event[]>([])
  const [status, setStatus] = useState('disconnected')

  useEffect(() => {
    const eventSource = new EventSource('/api/events')

    eventSource.onopen = () => {
      setStatus('connected')
    }

    eventSource.addEventListener('notification', (event) => {
      const data = JSON.parse(event.data)
      setEvents(prev => [...prev, { type: 'notification', data }])
    })

    eventSource.addEventListener('complete', (event) => {
      const data = JSON.parse(event.data)
      setEvents(prev => [...prev, { type: 'complete', data }])
      eventSource.close()
    })

    eventSource.onerror = () => {
      setStatus('error')
      eventSource.close()
    }

    return () => {
      eventSource.close()
    }
  }, [])

  return (
    <div>
      <p>Status: {status}</p>
      <ul>
        {events.map((event, i) => (
          <li key={i}>{JSON.stringify(event)}</li>
        ))}
      </ul>
    </div>
  )
}
```

